WITH matched_keys AS (SELECT device FROM sessions INTERSECT ALL SELECT device FROM sessions WHERE browser = 'Firefox'), reconciled AS (SELECT s.* FROM sessions s INNER JOIN matched_keys k ON s.device = k.device) SELECT browser, COUNT(*) FILTER (WHERE country = 'SG') AS sg_rows, COUNT_IF(browser = 'Chrome') AS chrome_events, SORT_ARRAY(COLLECT_SET(browser)) AS browser_list, MAX(started_at) AS ended_at, SORT_ARRAY(COLLECT_SET(country)) AS country_list FROM reconciled GROUP BY browser;
